import * as fs from "fs";
import * as path from "path";

// Copies the compiled ABIs into the frontend as typed `as const` arrays.
const root = path.join(__dirname, "..");
const read = (p: string) => JSON.parse(fs.readFileSync(path.join(root, "artifacts/contracts", p), "utf8")).abi;
const board = read("AgentTaskBoard.sol/AgentTaskBoard.json");
const mock = read("mocks/MockAgentID.sol/MockAgentID.json");
const out =
  "// Generated by scripts/export-abi.ts - do not edit by hand.\n" +
  `export const agentTaskBoardAbi = ${JSON.stringify(board, null, 2)} as const;\n\n` +
  `export const mockAgentIdAbi = ${JSON.stringify(mock, null, 2)} as const;\n`;
fs.writeFileSync(path.join(root, "frontend/src/lib/abi.ts"), out);
console.log("Wrote frontend/src/lib/abi.ts");
